use xiom.io;

fn print_and_drop(v: Vec[Int]) {
  io.println(v.len().to_str());
}

fn main() -> Int {
  let my_vec = Vec[Int].new();
  my_vec.push(10);
  my_vec.push(20);
  let len = my_vec.len();
  print_and_drop(my_vec);
  return len as Int;
}
